// Retrieve candidate profile from the Google Sheets node
const profile = $('Load Candidate Profile').first().json;

// Parse job listings from Decodo/RemoteOK response
let rawResponse = $input.first().json;
let jobs = [];

try {
  // Decodo wraps the scraped body — unwrap it
  let body = rawResponse.body !== undefined ? rawResponse.body : rawResponse;
  if (typeof body === 'string') body = JSON.parse(body);
  jobs = Array.isArray(body) ? body : [body];

  // RemoteOK: first element is a legal notice object, skip it
  if (jobs.length > 0 && (jobs[0].legal || !jobs[0].id)) {
    jobs = jobs.slice(1);
  }
} catch (e) {
  throw new Error('Failed to parse job listings from Decodo response: ' + e.message);
}

if (jobs.length === 0) {
  throw new Error('No job listings returned. Verify your Decodo API key and target URL.');
}

// Cap at 30 jobs per run to manage OpenAI API costs
const jobsToProcess = jobs.slice(0, 30);

return jobsToProcess.map((job, index) => ({
  json: {
    job_id: String(job.id || job.slug || ('job-' + Date.now() + '-' + index)),
    title: String(job.position || job.title || 'Unknown Position'),
    company: String(job.company || job.company_name || 'Unknown Company'),
    description: String(job.description || (Array.isArray(job.tags) ? job.tags.join(' ') : '')).substring(0, 800),
    url: String(job.url || job.apply_url || ''),
    location: String(job.location || 'Remote'),
    salary: job.salary ? String(job.salary) : (job.salary_min ? '$' + job.salary_min + '-$' + job.salary_max : ''),
    tags: Array.isArray(job.tags) ? job.tags.join(', ') : String(job.tags || ''),
    date_posted: job.epoch ? new Date(job.epoch * 1000).toISOString() : (job.date || new Date().toISOString()),
    // Candidate profile fields
    candidate_skills: String(profile.skills || ''),
    candidate_salary: String(profile.salary_expectation || ''),
    candidate_industries: String(profile.preferred_industries || '')
  }
}));

const job = $input.first().json;

const systemPrompt = 'You are an expert job matching assistant. Analyze how well a job listing matches a candidate profile. Return ONLY a valid JSON object with exactly these three fields: fit_score (integer 0-100, where 0=no match and 100=perfect match), reasoning (string, 1-2 sentence explanation, max 200 characters), match_highlights (array of exactly 3 strings highlighting key matching or mismatching points).';

const userMessage = [
  'JOB LISTING:',
  'Title: ' + job.title,
  'Company: ' + job.company,
  'Location: ' + job.location,
  'Salary: ' + (job.salary || 'Not specified'),
  'Required Skills/Tags: ' + job.tags,
  'Description: ' + job.description.substring(0, 600),
  '',
  'CANDIDATE PROFILE:',
  'Skills: ' + job.candidate_skills,
  'Expected Salary: ' + job.candidate_salary,
  'Preferred Industries: ' + job.candidate_industries,
  '',
  'Return JSON only with fit_score (0-100), reasoning (string), and match_highlights (array of 3 strings).'
].join('\n');

const requestBody = {
  model: 'gpt-4o-mini',
  response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: userMessage }
  ],
  max_tokens: 400,
  temperature: 0.2
};

// Preserve all original job fields + add prepared request body
return [{
  json: {
    ...job,
    openai_request_body: JSON.stringify(requestBody)
  }
}];

// Get original job data preserved in the Prepare AI Scoring Request node
const originalJob = $('Prepare AI Scoring Request').item.json;

// Get OpenAI API response
const openaiResponse = $input.first().json;

let aiResult = {
  fit_score: 0,
  reasoning: 'Unable to parse AI response',
  match_highlights: ['N/A', 'N/A', 'N/A']
};

try {
  if (openaiResponse.choices && openaiResponse.choices[0]) {
    const content = openaiResponse.choices[0].message.content;
    const parsed = typeof content === 'string' ? JSON.parse(content) : content;

    aiResult.fit_score = Math.min(100, Math.max(0, parseInt(parsed.fit_score) || 0));
    aiResult.reasoning = String(parsed.reasoning || '').substring(0, 200);

    if (Array.isArray(parsed.match_highlights)) {
      aiResult.match_highlights = parsed.match_highlights.slice(0, 3);
    } else if (typeof parsed.match_highlights === 'string') {
      aiResult.match_highlights = [parsed.match_highlights];
    }
  } else if (openaiResponse.error) {
    console.error('OpenAI API error:', openaiResponse.error.message);
  }
} catch (e) {
  console.error('Error parsing AI response:', e.message);
}

return [{
  json: {
    job_id: originalJob.job_id,
    title: originalJob.title,
    company: originalJob.company,
    url: originalJob.url,
    salary: originalJob.salary,
    tags: originalJob.tags,
    location: originalJob.location,
    date_posted: originalJob.date_posted,
    fit_score: aiResult.fit_score,
    reasoning: aiResult.reasoning,
    match_highlights: aiResult.match_highlights.join(' | '),
    scored_at: new Date().toISOString()
  }
}];
